INSERT INTO retail.produk (sku, nama, kategori, harga, stok, deskripsi, foto) VALUES
($q$TR-001$q$, $q$Tas Ransel Harian Hitam$q$, $q$Tas Ransel$q$, 189000, 18, $q$Tas Ransel Harian Hitam berbahan poliester hitam, berbentuk persegi panjang dengan sudut atas membulat. Dimensi 30 x 14 x 42 cm (lebar x tebal x tinggi). Memiliki satu kompartemen utama beritsleting, satu saku depan beritsleting horizontal, dua saku samping terbuka, dan dua tali bahu empuk. Cocok untuk kuliah dan kegiatan harian.$q$, $q$tr-001-ransel-harian-hitam.png$q$),
($q$TR-002$q$, $q$Tas Ransel Harian Biru Dongker$q$, $q$Tas Ransel$q$, 189000, 12, $q$Tas Ransel Harian Biru Dongker berbahan poliester biru dongker, berbentuk persegi panjang dengan sudut atas membulat. Dimensi 30 x 14 x 42 cm (lebar x tebal x tinggi). Memiliki satu kompartemen utama beritsleting, satu saku depan beritsleting horizontal, dua saku samping terbuka, dan dua tali bahu empuk. Cocok untuk kuliah dan kegiatan harian.$q$, $q$tr-002-ransel-harian-biru-dongker.png$q$),
($q$TR-003$q$, $q$Tas Ransel Kanvas Krem$q$, $q$Tas Ransel$q$, 219000, 9, $q$Tas Ransel Kanvas Krem berbahan kanvas krem, berbentuk kotak tegak dengan penutup lipat dan dua gesper cokelat. Dimensi 28 x 13 x 38 cm (lebar x tebal x tinggi). Memiliki satu ruang utama bertali serut di bawah penutup, satu saku depan bertutup, dua saku samping terbuka, dan dua tali bahu. Cocok untuk membawa buku dan perlengkapan jalan-jalan.$q$, $q$tr-003-ransel-kanvas-krem.png$q$),
($q$TR-004$q$, $q$Tas Ransel Gulung Hijau Zaitun$q$, $q$Tas Ransel$q$, 249000, 7, $q$Tas Ransel Gulung Hijau Zaitun berbahan nilon hijau zaitun, berbentuk memanjang dengan penutup atas gulung dan satu gesper hitam. Dimensi 29 x 14 x 44 cm (lebar x tebal x tinggi). Memiliki satu kompartemen utama, satu saku depan beritsleting vertikal, dua saku samping terbuka, dan dua tali bahu. Cocok untuk perjalanan harian dan membawa pakaian ganti.$q$, $q$tr-004-ransel-gulung-hijau-zaitun.png$q$),
($q$TR-005$q$, $q$Tas Ransel Mini Merah Muda$q$, $q$Tas Ransel$q$, 149000, 0, $q$Tas Ransel Mini Merah Muda berbahan kulit sintetis merah muda pastel, berbentuk kecil dengan bagian atas melengkung. Dimensi 22 x 10 x 28 cm (lebar x tebal x tinggi). Memiliki satu kompartemen utama beritsleting, satu saku depan beritsleting, pegangan atas, dan dua tali bahu yang dapat diatur. Cocok untuk membawa dompet dan barang kecil saat bepergian.$q$, $q$tr-005-ransel-mini-merah-muda.png$q$),
($q$TR-006$q$, $q$Tas Ransel Mini Ungu Pastel$q$, $q$Tas Ransel$q$, 149000, 14, $q$Tas Ransel Mini Ungu Pastel berbahan kulit sintetis ungu pastel, berbentuk kecil dengan bagian atas melengkung. Dimensi 22 x 10 x 28 cm (lebar x tebal x tinggi). Memiliki satu kompartemen utama beritsleting, satu saku depan beritsleting, pegangan atas, dan dua tali bahu yang dapat diatur. Cocok untuk membawa dompet dan barang kecil saat bepergian.$q$, $q$tr-006-ransel-mini-ungu-pastel.png$q$),
($q$TS-001$q$, $q$Tas Selempang Bulan Hitam$q$, $q$Tas Selempang$q$, 129000, 22, $q$Tas Selempang Bulan Hitam berbahan nilon hitam, berbentuk bulan sabit. Dimensi 28 x 8 x 17 cm (lebar x tebal x tinggi). Memiliki satu kompartemen utama beritsleting, satu saku kecil di dalam, dan tali lebar yang dapat diatur. Cocok untuk membawa ponsel dan dompet saat berjalan santai.$q$, $q$ts-001-selempang-bulan-hitam.png$q$),
($q$TS-002$q$, $q$Tas Selempang Bulan Krem$q$, $q$Tas Selempang$q$, 129000, 16, $q$Tas Selempang Bulan Krem berbahan nilon krem, berbentuk bulan sabit. Dimensi 28 x 8 x 17 cm (lebar x tebal x tinggi). Memiliki satu kompartemen utama beritsleting, satu saku kecil di dalam, dan tali lebar yang dapat diatur. Cocok untuk membawa ponsel dan dompet saat berjalan santai.$q$, $q$ts-002-selempang-bulan-krem.png$q$),
